#!/usr/bin/env python3
"""Materialize the reproducible v2.4 Final Android sources before CI build."""
from pathlib import Path
import base64
import gzip

FILES = {
    'device_lab_v2/app/src/main/java/com/ttclab/chatbridge/BridgeService.kt': '',
    'device_lab_v2/app/src/main/java/com/ttclab/chatbridge/BridgeAccessibilityService.kt': '',
    'device_lab_v2/app/src/main/java/com/ttclab/chatbridge/ScreenAnalyzer.kt': '',
    'device_lab_v2/app/build.gradle.kts': '',
    'device_lab_v2/app/src/main/res/values/strings.xml': '',
}

for relative_path, payload in FILES.items():
    target = Path(relative_path)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_bytes(gzip.decompress(base64.b64decode(payload)))
    print(f"materialized {target}")
